local a=require("basalt")local b=a.use("theme").applyPreset("basalt")local c=a.getMainFrame()local d=math.min(42,width-4)local e=math.min(13,height-2)local f=main:addFrame({x=math.floor((width-d)/2)+1,y=math.floor((height-e)/2)+1,width=d,height=e,background=b.surface})f:addLabel({x=2,y=2,text="My first Basalt app",foreground=b.lava})f:addLabel({x=2,y=4,width=d-4,height=2,text="Enter your name and press the button.",foreground=b.muted})f:addLabel({x=2,y=7,text="Name:"})local g=f:addInput({x=9,y=7,width=d-11,placeholder="Steve"})local h=f:addLabel({x=2,y=9,width=d-4,text="Waiting for input...",foreground=b.muted})local function i()local j=g.text:match("^%s*(.-)%s*$")if j==""then h.text="Please enter your name."h.foreground=b.warning;return end;h.text="Hello, "..j.."!"h.foreground=b.success end;f:addButton({x=2,y=11,width=12,height=1,text="Say hello",foreground=b.bg,background=b.lava}):onClick(i)f:addButton({x=d-9,y=11,width=8,height=1,text="Exit"}):onClick(function()a.stop()end)g:onEnter(i)g:focus()a.run()
